/**
 * @file ota_crypto.h
 * @brief OTA crypto seam over mbedTLS (private to FirmwareStore).
 *
 * Including this header links ota_crypto.c, and with it mbedTLS. Unit tests that
 * fake the crypto include ota_crypto_types.h instead.
 *
 * @see docs/lld/middleware/firmware-store.md §11
 */

#ifndef OTA_CRYPTO_H
#define OTA_CRYPTO_H

#include "ota_crypto_types.h"

/**
 * Raw P-256 release public key, X || Y. Generated by tools/ota/make_image.py
 * into ota_public_key.c; the matching private key never enters git.
 */
extern const uint8_t ota_public_key[OTA_PUBLIC_KEY_LEN];

#endif /* OTA_CRYPTO_H */
